@app.cell
def _(mo, q1_summary, typical_peak):
    _s = q1_summary
    mo.md(
        f"""
        ### Answer

        Rain goes with much lower ridership in every quarter. Comparing hours that are
        otherwise alike, a rainy hour has about **{abs(_s['pooled_pct']):.0f}% fewer rides**
        overall, and between {abs(_s['max_pct']):.0f}% and {abs(_s['min_pct']):.0f}% fewer
        depending on the quarter (all Holm-adjusted
        p-values ≤ {_s['max_holm_p']:.2g}). At a typical dry weekday 17:00 with about
        {typical_peak:,.0f} rides, that is roughly **{typical_peak * -_s['pooled_pct'] / 100:,.0f}
        fewer rides in that hour** — far too large to be a technicality. The independent
        subset, whose p-value does not rely on independent hours, gives a similar effect
        ({_s['subset_pct']:.0f}%), though from only {_s['subset_wet']} rainy rows.

        **What this does not show.** It is an association, not proof that rain causes the
        drop: rainy hours may also differ in ways we did not measure (wind, darkness,
        storms that close stations, events cancelled for the same weather). One station
        stands in for the whole city, so a shower over Brooklyn that misses Central Park is
        counted as dry. The result is for New York in 2024 and may not hold in other cities
        or years.
        """
    )
    return


@app.cell
def _(mo):
    mo.md(
        r"""
        ## Question 2: Is the relationship between temperature and hourly ridership nonlinear?
        """
    )
    return


@app.cell
def _(CONTROLS, analysis, np, smf, subset, temp_mean):
    q2_linear = smf.ols(f"log_rides ~ tc + C(quarter) + {CONTROLS} + rain", data=analysis).fit()
    q2_quad = smf.ols(f"log_rides ~ tc + tc2 + C(quarter) + {CONTROLS} + rain", data=analysis).fit()
    q2_no_quarter = smf.ols(f"log_rides ~ tc + tc2 + {CONTROLS} + rain", data=analysis).fit()
    q2_subset = smf.ols("log_rides ~ tc + tc2 + rain + weekend + C(quarter)", data=subset).fit()

    _b1, _b2 = q2_quad.params["tc"], q2_quad.params["tc2"]
    _cov = q2_quad.cov_params().loc[["tc", "tc2"], ["tc", "tc2"]].to_numpy()
    _grad = np.array([-1 / (2 * _b2), _b1 / (2 * _b2**2)])
    _tp_se = float(np.sqrt(_grad @ _cov @ _grad))
    q2_turn = float(temp_mean - _b1 / (2 * _b2))
    q2_turn_ci = (q2_turn - 1.96 * _tp_se, q2_turn + 1.96 * _tp_se)

    def temp_effect(model, temp, ref=15.0):
        """% difference in rides at `temp` vs `ref` degrees C, from a fitted model."""
        def part(t):
            x = t - temp_mean
            return model.params["tc"] * x + model.params.get("tc2", 0.0) * x**2
        return 100 * (np.exp(part(temp) - part(ref)) - 1)

    return q2_linear, q2_no_quarter, q2_quad, q2_subset, q2_turn, q2_turn_ci, temp_effect


@app.cell
def _(analysis, mo):
    mo.md(
        f"""
        ### Approach

        **Method: comparing two linear regressions.** Both regress log rides on
        temperature with the same controls as Question 1 (hour × weekday/weekend, quarter,
        rain) on the same {len(analysis):,} hours. The second adds **temperature squared**.
        A curve is supported if the squared term's t-test rejects zero; its sign says which
        way the curve bends. Temperature is centred at its mean
        ({analysis['temperature_c'].mean():.1f} °C) before squaring so the two terms are
        not nearly collinear.

        **Why the hour controls matter here.** Afternoons are warmer than nights and are
        also busier for reasons that have nothing to do with weather. Without the hour
        controls, a temperature curve would largely re-describe the daily cycle of
        commuting. Because temperature and quarter move together, we also refit without the
        quarter terms and compare.

        **Assumptions and checks.** The model is the Question 1 model with one rain effect
        instead of four, so the same diagnostics apply: no strong pattern in the residuals,
        heavy tails, and strong hour-to-hour dependence. As in Question 1 we read the answer
        from the size and shape of the curve, and repeat the test on the independent
        subset. We only describe the curve within the observed range
        ({analysis['temperature_c'].min():.0f} to {analysis['temperature_c'].max():.0f} °C).
        """
    )
    return


@app.cell
def _(analysis, np, plt, q2_linear, q2_quad, temp_effect):
    _grid = np.linspace(analysis["temperature_c"].quantile(0.005), analysis["temperature_c"].quantile(0.995), 80)
    # Partial residuals: the quadratic model's residual plus its own temperature part, binned by 2 °C.
    _part = q2_quad.params["tc"] * analysis["tc"] + q2_quad.params["tc2"] * analysis["tc2"]
    _partial = q2_quad.resid + _part
    _ref = q2_quad.params["tc"] * (15 - analysis["temperature_c"].mean()) + q2_quad.params["tc2"] * (15 - analysis["temperature_c"].mean()) ** 2
    _bins = (analysis["temperature_c"] // 2) * 2 + 1
    _binned = (_partial - _ref).groupby(_bins).agg(["mean", "size"])
    _binned = _binned[_binned["size"] >= 30]
    _fig, _ax = plt.subplots(figsize=(7.5, 4))
    _ax.scatter(_binned.index, 100 * (np.exp(_binned["mean"]) - 1), color="grey", s=18, label="Observed (2 °C bins, adjusted)")
    _ax.plot(_grid, [temp_effect(q2_quad, t) for t in _grid], lw=2, label="Quadratic model")
    _ax.plot(_grid, [temp_effect(q2_linear, t) for t in _grid], lw=2, ls="--", label="Linear model")
    _ax.axhline(0, color="black", lw=0.8)
    _ax.set(xlabel="Temperature (°C)", ylabel="% difference in rides vs 15 °C", title="Ridership rises with temperature, flattening when hot")
    _ax.legend(fontsize=8)
    _fig.tight_layout()
    _fig
    return


@app.cell
def _(fmt_p, mo, q2_linear, q2_no_quarter, q2_quad, q2_subset, q2_turn, q2_turn_ci, temp_effect, temp_mean):
    q2_summary = {
        "b2": float(q2_quad.params["tc2"]),
        "t": float(q2_quad.tvalues["tc2"]),
        "p": float(q2_quad.pvalues["tc2"]),
        "n": int(q2_quad.nobs),
        "adj_r2_lin": float(q2_linear.rsquared_adj),
        "adj_r2_quad": float(q2_quad.rsquared_adj),
        "at5": float(temp_effect(q2_quad, 5)),
        "at25": float(temp_effect(q2_quad, 25)),
        "at30": float(temp_effect(q2_quad, 30)),
        "lin_at5": float(temp_effect(q2_linear, 5)),
        "lin_at30": float(temp_effect(q2_linear, 30)),
        "turn": q2_turn,
        "turn_lo": q2_turn_ci[0],
        "turn_hi": q2_turn_ci[1],
        "nq_b2": float(q2_no_quarter.params["tc2"]),
        "nq_turn": float(temp_mean - q2_no_quarter.params["tc"] / (2 * q2_no_quarter.params["tc2"])),
        "sub_b2": float(q2_subset.params["tc2"]),
        "sub_t": float(q2_subset.tvalues["tc2"]),
        "sub_p": float(q2_subset.pvalues["tc2"]),
        "sub_n": int(q2_subset.nobs),
    }
    _s = q2_summary
    mo.md(
        f"""
        ### Result

        **Squared temperature term:** coefficient {_s['b2']:.5f} (per °C²), t = {_s['t']:.1f},
        {fmt_p(_s['p'])}, N = {_s['n']:,} hours. Adjusted R² rises from {_s['adj_r2_lin']:.4f}
        (straight line) to {_s['adj_r2_quad']:.4f} (curve).

        **Effect size — the shape.** Relative to an otherwise similar 15 °C hour, the curve
        gives **{_s['at5']:+.0f}%** rides at 5 °C, **{_s['at25']:+.0f}%** at 25 °C and
        **{_s['at30']:+.0f}%** at 30 °C. A straight line would instead claim
        {_s['lin_at5']:+.0f}% at 5 °C and {_s['lin_at30']:+.0f}% at 30 °C, i.e. keep rising.
        The fitted curve peaks at **{_s['turn']:.1f} °C** (95% CI {_s['turn_lo']:.1f} to
        {_s['turn_hi']:.1f} °C), near the top of the observed range, so the data show the
        rise flattening in hot weather rather than a clear fall.

        **Checks.** Without the quarter terms the squared term is {_s['nq_b2']:.5f} and the
        peak {_s['nq_turn']:.1f} °C, so the shape is not an artefact of the season controls.
        On the independent subset (N = {_s['sub_n']}) the squared term is {_s['sub_b2']:.5f},
        t = {_s['sub_t']:.1f}, {fmt_p(_s['sub_p'])}.
        """
    )
    return (q2_summary,)


@app.cell
def _(mo, q2_summary):
    _s = q2_summary
    mo.md(
        f"""
        ### Answer

        Yes — the relationship is curved. Ridership climbs steeply from cold to mild
        weather and then levels off: compared with 15 °C, an otherwise similar hour has
        about {abs(_s['at5']):.0f}% fewer rides at 5 °C but only about {_s['at25']:.0f}% more
        at 25 °C, and the gain stops growing around {_s['turn']:.0f} °C. A straight line
        would overstate how much the hottest hours add.

        **What this does not show.** It does not show that heat itself discourages riding:
        the flattening could come from humidity, summer holidays or tourists, which we do
        not measure, and New York in 2024 had few very hot hours, so the top of the curve
        rests on little data. The curve also does not identify an exact "best" temperature —
        its interval is several degrees wide.
        """
    )
    return


@app.cell
def _(mo):
    mo.md(
        r"""
        ## Question 3: Does the precipitation–ridership relationship differ between weekdays and weekends?
        """
    )
    return


@app.cell
def _(CONTROLS, analysis, smf, subset):
    q3_model = smf.ols(
        f"log_rides ~ rain * weekend + C(quarter) + {CONTROLS} + tc + tc2", data=analysis
    ).fit()
    q3_subset = smf.ols("log_rides ~ rain * weekend + C(quarter) + tc + tc2", data=subset).fit()
    q3_cells = (
        analysis.groupby(["weekend", "rain"])["rides"]
        .agg(hours="size", median_rides="median")
        .reset_index()
        .replace({"weekend": {0: "weekday", 1: "weekend"}, "rain": {0: "dry", 1: "rainy"}})
    )
    q3_subset_cells = subset.groupby(["weekend", "rain"]).size()
    return q3_cells, q3_model, q3_subset, q3_subset_cells


@app.cell
def _(mo, q3_subset_cells):
    mo.md(
        f"""
        ### Approach

        **Method: linear regression with an interaction.** We add `rain × weekend` to the
        Question 1 model (one rain effect, controls for hour × weekday/weekend, quarter and
        temperature). The interaction coefficient is the difference between the weekend and
        the weekday rain effect on the log scale, and its t-test asks whether that
        difference is zero. Because the model already lets weekdays and weekends have
        different hourly profiles, the interaction is not just "weekends have no commuting
        peaks".

        **Effect size on the percentage scale.** We report the rain effect separately for
        weekdays and weekends as % changes. A difference in percentages can disagree with a
        difference in absolute rides, because weekday peaks are larger; we give both.

        **Assumptions and checks.** Same model family and diagnostics as Question 1:
        acceptable residual pattern, heavy tails, strong dependence between consecutive
        hours, so we read the effect size and re-test on the independent subset. Rainy
        weekend hours are the smallest group (counts in the Result); in the independent
        subset there are only **{int(q3_subset_cells.get((1, 1), 0))}**, which makes the
        subset test weak.
        """
    )
    return


@app.cell
def _(contrast, fmt_p, mo, pct, q3_cells, q3_model, q3_subset, typical_peak):
    _wd = contrast(q3_model, ["rain"])
    _we = contrast(q3_model, ["rain", "rain:weekend"])
    _typical_weekend = float(
        q3_model.model.data.frame.loc[
            (q3_model.model.data.frame["hour_of_day"] == 14)
            & (q3_model.model.data.frame["weekend"] == 1)
            & (q3_model.model.data.frame["rain"] == 0),
            "rides",
        ].median()
    )
    q3_summary = {
        "inter": float(q3_model.params["rain:weekend"]),
        "inter_lo": float(q3_model.conf_int().loc["rain:weekend", 0]),
        "inter_hi": float(q3_model.conf_int().loc["rain:weekend", 1]),
        "t": float(q3_model.tvalues["rain:weekend"]),
        "p": float(q3_model.pvalues["rain:weekend"]),
        "n": int(q3_model.nobs),
        "wd": pct(_wd["estimate"]),
        "wd_lo": pct(_wd["lo"]),
        "wd_hi": pct(_wd["hi"]),
        "we": pct(_we["estimate"]),
        "we_lo": pct(_we["lo"]),
        "we_hi": pct(_we["hi"]),
        "wd_abs": typical_peak * pct(_wd["estimate"]) / 100,
        "we_abs": _typical_weekend * pct(_we["estimate"]) / 100,
        "typical_weekend": _typical_weekend,
        "sub_inter": float(q3_subset.params["rain:weekend"]),
        "sub_t": float(q3_subset.tvalues["rain:weekend"]),
        "sub_p": float(q3_subset.pvalues["rain:weekend"]),
        "sub_n": int(q3_subset.nobs),
    }
    _s = q3_summary
    mo.vstack(
        [
            mo.md("### Result"),
            mo.ui.table(q3_cells.round(0), pagination=False, selection=None),
            mo.md(
                f"""
                **Interaction (rain × weekend):** {_s['inter']:.3f} on the log scale (95% CI
                {_s['inter_lo']:.3f} to {_s['inter_hi']:.3f}), t = {_s['t']:.1f}, {fmt_p(_s['p'])},
                N = {_s['n']:,} hours.

                **Effect size.** Change in rides in a rainy hour: **{_s['wd']:.1f}%** on weekdays
                (95% CI {_s['wd_lo']:.1f}% to {_s['wd_hi']:.1f}%) and **{_s['we']:.1f}%** on weekends
                ({_s['we_lo']:.1f}% to {_s['we_hi']:.1f}%) — a gap of
                {abs(_s['we'] - _s['wd']):.1f} percentage points. In rides: about
                {abs(_s['wd_abs']):,.0f} fewer at a typical weekday 17:00 (≈{typical_peak:,.0f}
                rides when dry) and about {abs(_s['we_abs']):,.0f} fewer at a typical weekend
                14:00 (≈{_s['typical_weekend']:,.0f} rides when dry).

                **Independent subset** (N = {_s['sub_n']}): interaction {_s['sub_inter']:.3f},
                t = {_s['sub_t']:.1f}, {fmt_p(_s['sub_p'])}.
                """
            ),
        ]
    )
    return (q3_summary,)


@app.cell
def _(plt, q3_summary):
    _fig, _ax = plt.subplots(figsize=(6, 3.6))
    _vals = [q3_summary["wd"], q3_summary["we"]]
    _err = [
        [q3_summary["wd"] - q3_summary["wd_lo"], q3_summary["we"] - q3_summary["we_lo"]],
        [q3_summary["wd_hi"] - q3_summary["wd"], q3_summary["we_hi"] - q3_summary["we"]],
    ]
    _ax.bar(["Weekdays", "Weekends"], _vals, yerr=_err, capsize=6, color=["tab:blue", "tab:green"])
    _ax.axhline(0, color="black", lw=0.8)
    _ax.set(ylabel="% change in rides, rainy vs dry hour", title="Rain cuts a larger share of weekend rides", ylim=(-100, 0))
    _fig.tight_layout()
    _fig
    return


@app.cell
def _(mo, q3_summary):
    _s = q3_summary
    mo.md(
        f"""
        ### Answer

        Yes, modestly. Rain is linked to a drop on both kinds of day, but a larger share of
        weekend riders disappear: about {abs(_s['we']):.0f}% fewer rides in a rainy weekend
        hour against {abs(_s['wd']):.0f}% on weekdays, holding time of day, quarter and
        temperature fixed. The gap is real in the full data but small next to the rain
        effect itself, and the independent subset — with very few rainy weekend hours —
        can only weakly confirm it ({'p = ' + format(_s['sub_p'], '.3f')}).

        **What this does not show.** It does not tell us *why* weekend riders are more
        sensitive; the obvious explanation (weekend trips are optional leisure trips while
        weekday trips are commutes) is plausible but untested here, since trip purpose is
        not in the data. In absolute numbers the picture can reverse, because a busy weekday
        peak loses more riders even at a smaller percentage.
        """
    )
    return


@app.cell
def _(CONTROLS, analysis, hourly, np, pct, pd, smf, weather_comparison):
    # --- Decision 1: weather source (station vs. model-based) ---
    _om = hourly.dropna(subset=["hourly_rides", "om_precip_mm", "om_temp_c"]).copy()
    _om["log_rides"] = np.log1p(_om["hourly_rides"].astype(float))
    _om["rain"] = (_om["om_precip_mm"] >= 0.2).astype(int)
    _om["weekend"] = _om["is_weekend"].astype(bool).astype(int)
    _om["tc"] = _om["om_temp_c"] - _om["om_temp_c"].mean()
    _om["tc2"] = _om["tc"] ** 2
    _m_om = smf.ols(f"log_rides ~ rain + C(quarter) + {CONTROLS} + tc + tc2", data=_om).fit()
    _w = pd.to_numeric(weather_comparison, errors="coerce")

    # --- Decision 2: log vs raw rides ---
    _m_log = smf.ols(f"log_rides ~ rain + C(quarter) + {CONTROLS} + tc + tc2", data=analysis).fit()
    _m_raw = smf.ols(f"rides ~ rain + C(quarter) + {CONTROLS} + tc + tc2", data=analysis).fit()
    _fit_raw = _m_raw.fittedvalues
    _top = _fit_raw >= _fit_raw.quantile(0.9)
    _bottom = _fit_raw <= _fit_raw.quantile(0.1)
    _wet_neg = int(((_fit_raw < 0) & (analysis["rain"] == 1)).sum())
    _night_dry = float(analysis.loc[(analysis["hour_of_day"] == 4) & (analysis["rain"] == 0), "rides"].median())
    _top_log = _m_log.fittedvalues >= _m_log.fittedvalues.quantile(0.9)
    _bottom_log = _m_log.fittedvalues <= _m_log.fittedvalues.quantile(0.1)

    # --- Decision 3: within-quarter, like-for-like comparison vs unadjusted pooled ---
    _m_unadj = smf.ols("log_rides ~ rain", data=analysis).fit()
    _rain_share_q = analysis.groupby("quarter")["rain"].mean() * 100
    _night = analysis["hour_of_day"].between(0, 5)

    decisions = {
        "lcd_wet_share": 100 * _w["lcd_wet_share_ge_0.2"],
        "om_wet_share": 100 * _w["om_wet_share_ge_0.2"],
        "disagree_any_wet": 100 * _w["wet_dry_disagreement_among_any_wet"],
        "precip_corr": _w["precip_correlation"],
        "om_lat": _w["om_grid_latitude"],
        "om_lon": _w["om_grid_longitude"],
        "lcd_coverage": 100 * (1 - _w["lcd_hours_missing_precip"] / 8784),
        "lcd_effect": pct(_m_log.params["rain"]),
        "om_effect": pct(_m_om.params["rain"]),
        "raw_rain": float(_m_raw.params["rain"]),
        "night_dry": _night_dry,
        "raw_wet_negative": _wet_neg,
        "raw_spread_ratio": float(_m_raw.resid[_top].std() / _m_raw.resid[_bottom].std()),
        "log_spread_ratio": float(_m_log.resid[_top_log].std() / _m_log.resid[_bottom_log].std()),
        "unadjusted": pct(_m_unadj.params["rain"]),
        "adjusted": pct(_m_log.params["rain"]),
        "rain_share_q": _rain_share_q.round(1).to_dict(),
        "night_share_rainy": 100 * float(_night[analysis["rain"] == 1].mean()),
        "night_share_dry": 100 * float(_night[analysis["rain"] == 0].mean()),
        "temp_rainy": float(analysis.loc[analysis["rain"] == 1, "temperature_c"].mean()),
        "temp_dry": float(analysis.loc[analysis["rain"] == 0, "temperature_c"].mean()),
    }
    return (decisions,)


@app.cell
def _(mo, q1_summary, q2_summary, q3_summary):
    mo.md(
        f"""
        ## Summary of findings

        We counted the 44 million Citi Bike rides taken in New York in 2024 by the hour
        they began and matched each hour with Central Park's rain and temperature. Each
        rainy hour was compared with dry hours at the same time of day, kind of day,
        season and temperature.

        **Rain:** rides fall sharply when it rains, in every season. A rainy hour has
        about **{abs(q1_summary['pooled_pct']):.0f}% fewer rides** than a similar dry hour.

        **Temperature:** the link is curved. Riding climbs quickly as cold weather turns
        mild, then levels off in summer: 5 °C has about
        **{abs(q2_summary['at5']):.0f}% fewer rides** than 15 °C, while 25 °C adds only
        about {q2_summary['at25']:.0f}%.

        **Weekdays and weekends:** rain hits weekend riding a little harder —
        **{abs(q3_summary['we']):.0f}% fewer rides** in a rainy weekend hour against
        {abs(q3_summary['wd']):.0f}% on weekdays — perhaps because weekend trips are easier
        to skip.

        **Main limitation:** these are patterns, not proof of cause. Neighbouring hours
        are alike, so the data hold far fewer independent observations than their 8,700
        rows suggest, and one station and one year stand in for a whole city and other
        years.
        """
    )
    return


@app.cell
def _(decisions, mo):
    _d = decisions
    mo.md(
        f"""
        ## Decision log

        **1. Weather source for hourly rain.**
        **Decision.** We used the NOAA hourly observations from the Central Park station.
        **Alternative.** Open-Meteo, a model-based ("reanalysis") weather series that has a
        value for every hour and no gaps.
        **Evidence.** The station is missing rain in only {100 - _d['lcd_coverage']:.1f}% of
        hours. Open-Meteo's nearest grid cell sits at {_d['om_lat']:.2f}, {_d['om_lon']:.2f} —
        across the Hudson in New Jersey — and smooths rain in space and time: it calls
        {_d['om_wet_share']:.1f}% of hours rainy against the station's {_d['lcd_wet_share']:.1f}%,
        and in hours where either source reports rain they disagree about whether it rained
        {_d['disagree_any_wet']:.0f}% of the time (hourly correlation {_d['precip_corr']:.2f}).
        **Consequence (run).** Refitting the pooled Question 1 model with Open-Meteo rain
        shrinks the rain effect from {_d['lcd_effect']:.1f}% to **{_d['om_effect']:.1f}%**:
        smoothed rain mixes dry hours into the "rainy" group and weakens the very drop
        Question 1 is about.

        **2. Log of rides as the outcome.**
        **Decision.** We modelled log(rides + 1) and report effects as percentages.
        **Alternative.** Modelling rides per hour directly.
        **Evidence.** On the raw scale the spread of the residuals in the busiest tenth of
        hours is {_d['raw_spread_ratio']:.1f} times that in the quietest tenth (log scale:
        {_d['log_spread_ratio']:.1f}), so the equal-spread assumption fails badly.
        **Consequence (run).** The raw model says rain removes the same
        {abs(_d['raw_rain']):,.0f} rides in every hour — more than the {_d['night_dry']:,.0f}
        rides in a typical dry 4 AM hour — and predicts a *negative* number of rides for
        {_d['raw_wet_negative']:,} rainy hours. The log model gives one sensible proportional
        effect at every hour.

        **3. Comparing like with like within quarters.**
        **Decision.** Rainy hours are compared with dry hours of the same quarter, hour,
        kind of day and temperature.
        **Alternative.** A simple comparison of all rainy with all dry hours across the
        year.
        **Evidence.** Rain is not spread evenly. The share of hours that are rainy is
        {', '.join(f'{k} {v}%' for k, v in _d['rain_share_q'].items())}; {_d['night_share_rainy']:.0f}%
        of rainy hours fall between midnight and 6 AM against {_d['night_share_dry']:.0f}% of dry
        hours; and rainy hours average {_d['temp_rainy']:.1f} °C against {_d['temp_dry']:.1f} °C.
        Season, time of day and temperature all affect riding on their own.  
        **Consequence (run).** The unadjusted comparison gives **{_d['unadjusted']:.1f}%**,
        against {_d['adjusted']:.1f}% for the like-for-like model — the simple comparison
        credits rain with part of the drop that is really due to the time of day and the
        season.
        """
    )
    return


if __name__ == "__main__":
    app.run()
